      paint: { backgroundColor: " RGBA(0, 0, 0, 0) " }
    };
    invalid.nodes[0].children = [transparentContainer.id];
    invalid.nodes[1].parentId = transparentContainer.id;
    invalid.nodes.push(transparentContainer);

